docs/voice-and-tone.md\",\n    \"docs/voice-and-tone.zh-CN.md\",\n    \"docs/feature-tiers.md\",\n    \"docs/validation/2026-10-01-context-boundaries.md\",\n    \"docs/plans/2026-09-27-1945-feat-evidence-based-learning-plan.md\",\n    \"docs/handoffs/2026-09-27-learning-workflow-redesign.md\",\n    \"docs/user-feedback-intake.md\",\n    \"docs/plans/2026-10-01-studyhub-overhaul.md\",\n    \"docs/requirements/studyhub-workflows.md\",\n    \"docs/plans/2026-09-30-0016-feat-quiet-product-integration-plan.md\",\n    \"docs/quiet-product-integration-verification.md\"\n  ],\n  \"license\": \"MIT\",\n  \"engines\": {\n    \"node\": \">=22.19\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": [\n        \"./cordis.patch.yml\",\n        \"./presets/study.patch.yml\",\n        \"./presets/study-worker.patch.yml\"\n      ]\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-store\"\n      ]\n    }\n  },\n  \"scripts\": {\n    \"build\": \"node scripts/build.mjs\",\n    \"prepare\": \"node scripts/prepare.mjs\",\n    \"build:demo\": \"node scripts/build-demo.mjs\",\n    \"test\": \"node scripts/test.mjs\",\n    \"test:fast\": \"node scripts/test.mjs --fast\",\n    \"case-study\": \"node scripts/case-study/build.mjs --out docs/case-study/studyhub-case-study.pdf --write-facts\",\n    \"lint\": \"eslint --cache --cache-location node_modules/.cache/eslint/ lib scripts tests ui packages eslint.config.js\",\n    \"dev\": \"node scripts/dev.mjs\",\n    \"qa:journey\": \"node scripts/qa/journey.mjs\",\n    \"qa:dismiss\": \"node scripts/qa/dismiss-timing.mjs\",\n    \"qa:selection-job\": \"node scripts/qa/selection-job.mjs\",\n    \"qa:outline\": \"node scripts/qa/outline.mjs\",\n    \"qa:translation\": \"node scripts/qa/translation.mjs\",\n    \"qa:reading-loop\": \"node scripts/qa/reading-loop.mjs\",\n    \"qa:sections-reader\": \"node scripts/qa/sections-reader.mjs\",\n    \"qa:archify\": \"node scripts/qa/archify.