"schemastery\": \"^3.18.0\",\n    \"yaml\": \"^2.8.1\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.5\",\n    \"@deepseek-ai/dsh-invariants\": \"^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-llm\": \"^0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-ptc-runtime\": \"^0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-sandbox\": \"^0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-sandbox-policy\": \"^0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-scope\": \"^0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-system-prompt\": \"^0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-tools\": \"^0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-user-approval\": \"^0.2.1-rc.2\",\n    \"@fontsource-variable/inter\": \"^5.3.0\",\n    \"@phosphor-icons/core\": \"^2.1.1\",\n    \"@playwright/test\": \"^1.55.0\",\n    \"esbuild\": \"^0.25.0\",\n    \"eslint\": \"^10.10.0\",\n    \"eslint-plugin-react\": \"^7.37.5\",\n    \"eslint-plugin-react-hooks\": \"^7.1.1\",\n    \"globals\": \"^17.12.0\",\n    \"react\": \"^19.0.0\",\n    \"react-dom\": \"^19.0.0\",\n    \"ts-fsrs\": \"5.4.2\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh-llm\": \">=0.2.0-rc.2 <0.3\",\n    \"@deepseek-ai/dsh-tools\": \">=0.2.0-rc.2 <0.3\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-tools\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-llm\": {\n      \"optional\": true\n    }\n  },\n  \"author\": \"ericwang1358 (https://github.com/EricWang1358)\"\n}\n"
