      "path": "lib/contexts/generation/selection.js",
      "content": "import { createHash, randomUUID } from 'node:crypto';\nimport { generateDeck, mentionsCard, reviewDeck } from '../../generation.js';\nimport { validateDeck } from '../../domain.js';\nimport { answerLeakIssues, explanationIssues, formulaIssues, learnerContextIssues, reviewIssues } from '../../assessment-quality.js';\nimport { ownWork } from '../../runtime/work-ownership.js';\nimport { selectionEvidenceText } from '../../selection-evidence.js';\nimport { createSelectionJobs } from './selection-jobs.js';\nimport { resolveNotation } from '../../notation.js';\n\n/** What a job says while the reviewed questions are being saved (its stage code is `publishing`). */\nexport const SAVE_STAGE = 'Publishing reviewed questions into the requested deck';\nimport { buildQaCard, checkedQaRequest, qaCourse, sourceQaWords } from './source-qa.js';\n\nconst kinds = ['quiz', 'multi', 'open', 'flashcard', 'cloze'];\nconst clone = value => structuredClone(value);\nfunction canonical(value) {\n  if (Array.isArray(value)) return value.map(canonical);\n  if (value && typeof value === 'object')\n    return Object.fromEntries(Object.keys(value).sort().map(key => [key, canonical(value[key])]));\n  return value;\n}\nconst digest = value => createHash('sha256').update(JSON.stringify(canonical(value))).digest('hex');\nconst errorText = error => error?.message || String(error);\n\n/** Model orchestration owns its candidates; publication is exclusively a bank API. */\nexport function createSelectionOperations({ root, read, update, materials, bank, complete, active = new Map(), workOwner, jobs: jobPorts }) {\n  const ownedControllers = new Set();\n  const get = async operationId => clone((await read()).selectionJobs.find(job => job.operationId === operationId));\n  const save = async (operationId, patch) => update(state => {\n    state.selectionJobs ||= [];\n    const job = state.selectionJobs.find(item => item.operationId === operationId);\n    if (!job) throw new Error('Selection operation does not exist');\n    Object.assign(job, clone(patch), { updatedAt: new Date().toISOString() });\n    return job;\n  });\n  const requireJob = async args => {\n    const job = await get(args.operationId);\n    if (!job) throw new Error('Selection operation does not exist');\n    return job;\n  };\n  const modelFor = request => {\n    const model = request?.complete || complete;\n    if (typeof model !== 'function') throw Object.assign(new Error('A model is required for selected-text generation'), { code: 'CAPABILITY_UNAVAILABLE' });\n    // The context the pipeline names (a review re-ask says `kind: 'review', retry`) goes on to the model, so a call is told apart from its siblings.\n    return (system, prompt, context = {}) => {\n      request?.signal?.throwIfAborted();\n      return model(system, prompt, { stage: 'Selection generation', ...context, signal: request?.signal, resultOwner: 'plugin' });\n    };\n  };\n  const resolve = async (selection, request) => {\n    const result = await materials('materials.selection.resolve', selection, request);\n    if (result.status !== 'resolved')\n      throw Object.assign(new Error(`Selection is ${result.status}; select the current passage again`), { code: 'POSITION_CONFLICT' });\n    return result.selection;\n  };\n  const evidence = async (selection, request) => {\n    const document = await materials('materials.document.get', { documentId: selection.documentId, sourceId: selection.sourceId }, request);\n    const source = document.sources?.find(item => item.id === selection.sourceId);\n    if (!source) throw new Error('Selection source is unavailable');\n    // A short table cell needs its nearby labels as evidence (lib/selection-evidence.js).\n    return [{ id: source.id, title: source.title || document.title || 'Selected material', text: selectionEvidenceText(source.text, selection) }];\n  };\n  const commit = async (job, expectedVersion, request) => {\n    if (job.status === 'complete') return job;\n    if (!job.accepted?.length || !job.reviewPassed) throw new Error('No independently reviewed questions are available to append');\n    try {\n      request?.signal?.throwIfAborted();\n      request?.onProgress?.({ stage: SAVE_STAGE, operationId: job.operationId });\n      // Bank owns validation under the commit lock and replays an existing receipt\n      // before checking a now-stale document. A preflight here would block recovery.\n      const receipt = await bank.append({ deckId: job.deckId, cards: job.accepted, selection: job.selection,\n        operationId: job.operationId, expectedVersion: expectedVersion ?? job.expectedVersion }, request);\n      return save(job.operationId, { status: 'complete', receipt, error: null });\n    } catch (error) {\n      return save(job.operationId, { status: request?.signal?.aborted ? 'cancelled' : 'conflict', error: errorText(error), errorCode: error.code });\n    }\n  };\n  const exclusive = (operationId, request, run, fingerprint = null) => {\n    const key = `${root}\\0${operationId}`;\n    const current = active.get(key);\n    if (current) {\n      if (fingerprint && current.fingerprint !== fingerprint) throw new Error('Operation ID was already used for a different concurrent request');\n      return current.promise;\n    }\n    const controller = new AbortController();\n    ownedControllers.add(controller);\n    const signal = request?.signal ? AbortSignal.any([request.signal, controller.signal]) : controller.signal;\n    const promise = Promise.resolve().then(() => run({ ...request, signal })).finally(() => {\n      active.delete(key);\n      ownedControllers.delete(controller);\n    });\n    active.set(key, ownWork({ fingerprint, promise, controller }, request?.workOwner ?? workOwner));\n    return promise;\n  };\n  /** The request as every entry point validates it: a deck, a stable operation id, a selection, 1–20 questions of a known kind. */\n  const normalize = args => {\n    if (typeof args.deckId !== 'string' || !args.deckId) throw new Error('Choose an existing destination deck');\n    if (typeof args.operationId !== 'string' || !args.operationId || args.operationId.length > 200)\n      throw new Error('A stable operationId is required');\n    if (!args.selection || typeof args.selection.quote !== 'string') throw new Error('A material selection is required');\n    const count = args.count ?? 1, kind = args.kind || 'flashcard';\n    if (!Number.isInteger(count) || count < 1 || count > 20) throw new Error('Question count must be between 1 and 20');\n    if (!kinds.includes(kind)) throw new Error('Unsupported question kind');\n    return { count, kind, fingerprint: digest({ ...args, count, kind }) };\n  };\n  const clear = operationId => update(state => { state.selectionJobs = (state.selectionJobs || []).filter(job => job.operationId !== operationId); });\n  const supplement = async (args, request = {}) => {\n    const { count, kind, fingerprint } = normalize(args);\n    const previous = await get(args.operationId);\n    if (previous && previous.fingerprint !== fingerprint) throw new Error('Operation ID was already used for a different request');\n    if (previous?.status === 'reviewed' && previous.reviewPassed)\n      return exclusive(args.operationId, request, scoped => commit(previous, undefined, scoped), fingerprint);\n    if (previous && !['preparing', 'writing', 'reviewing'].includes(previous.status)) return previous;\n    modelFor(request);\n    return exclusive(args.operationId, request, async scopedRequest => {\n      const existing = await get(args.operationId);\n      if (existing && existing.fingerprint !== fingerprint) throw new Error('Operation ID was already used for a different request');\n      if (existing?.reviewPassed) return commit(existing, undefined, scopedRequest);\n      const selection = await resolve(args.selection, scopedRequest);\n      const destination = await bank.get(args.deckId);\n      const deck = destination.deck || destination;\n      if (!Array.isArray(deck.cards)) throw new Error('Destination deck is unavailable');\n      const expectedVersion = args.expectedVersion ?? destination.version ?? deck.contentVersion ?? 0;\n      const sources = await evidence(selection, scopedRequest);\n      await update(state => {\n        state.selectionJobs ||= [];\n        if (state.selectionJobs.some(job => job.operationId === args.operationId)) return;\n        state.selectionJobs.push({ operationId: args.operationId, fingerprint, deckId: args.deckId, deckTitle: deck.title || '', expectedVersion,\n          selection, request: { count, kind, focus: args.focus || '' }, sources, status: 'preparing', candidates: [], accepted: [],\n          reviewPassed: false, createdAt: new Date().toISOString() });\n      });\n      try {\n        const draft = await generateDeck(modelFor(scopedRequest), {\n          count, kind, sources, notation: resolveNotation('auto', sources), existing: deck.cards.map(card => card.objective).filter(Boolean),\n          language: args.language || (scopedRequest.language === 'en' ? 'English' : '中文'), focus: `${args.focus || ''}\\nSelected passage: ${selection.quote}`,\n          onAuthored: async draft => {\n            await save(args.operationId, { candidates: draft.cards, candidateTitle: draft.title, status: 'reviewing' });\n            scopedRequest.onProgress?.({ written: draft.cards.length, operationId: args.operationId });\n          },\n          onReviewed: review => save(args.operationId, { review }),\n        }, stage => scopedRequest.onProgress?.({ stage, operationId: args.operationId }));\n        const accepted = draft.cards.map(card => ({ ...card, selections: [clone(selection)] }));\n        scopedRequest.onProgress?.({ passed: accepted.length, operationId: args.operationId });\n        const job = await save(args.operationId, { accepted, editorial: draft.editorial, reviewPassed: true, status: 'reviewed' });\n        return commit(job, undefined, scopedRequest);\n      } catch (error) {\n        return save(args.operationId, { status: scopedRequest.signal.aborted ? 'cancelled' : 'review-failed', error: errorText(error), accepted: [], reviewPassed: false });\n      }\n    }, fingerprint);\n  };\n  /** A grounded answer becomes one flashcard. No model: the text on screen is saved as it is. */\n  const saveAnswer = async (args, request = {}) => {\n    const { question, answer } = checkedQaRequest(args);\n    const english = (args.uiLanguage || request.language) === 'en';\n    const selection = await resolve(args.selection, request);\n    const document = await materials('materials.document.get', { documentId: selection.documentId, sourceId: selection.sourceId }, request);\n    const source = document.sources?.find(item => item.id === selection.sourceId);\n    if (!source) throw new Error('Selection source is unavailable');\n    const card = buildQaCard({ selection, source, title: document.title, question, answer, operationId: args.operationId, english });\n    for (let attempt = 0; ; attempt++) {\n      let deckId = args.deckId, expectedVersion = args.expectedVersion;\n      if (!deckId) {\n        const ensured = await bank.ensureDeck({ course: qaCourse(source), title: sourceQaWords(english).deck, purpose: 'source-qa' }, request);\n        deckId = ensured.deckId; expectedVersion = ensured.version;\n      } else if (expectedVersion === undefined) {\n        const destination = await bank.get(deckId, request);\n        expectedVersion = destination.version ?? destination.deck?.contentVersion ?? 0;\n      }\n      try {\n        const receipt = await bank.append({ deckId, cards: [card], selection, operationId: args.operationId, expectedVersion }, request);\n        return { status: 'complete', deckId, cardId: receipt.cardIds?.[0] ?? card.id, receipt };\n      } catch (error) {\n        const message = errorText(error);\n        if (/duplicates an existing question/.test(message)) {\n          const destination = await bank.get(deckId, request), existing = (destination.deck || destination).cards?.find(item => item.prompt === card.prompt);\n          return { status: 'duplicate', deckId, ...(existing ? { cardId: existing.id } : {}), error: message };\n        }\n        // A deck nobody chose can simply be re-read once; a chosen deck's version is the learner's to refresh.\n        if (/version conflict/i.test(message)) {\n          if (!args.deckId && attempt < 1) continue;\n          return { status: 'conflict', deckId, error: message };\n        }\n        throw error;\n      }\n    }\n  };\n  const handlers = {\n    'generation.selection.saveAnswer': saveAnswer,\n    'generation.selection.supplement': supplement,\n    'generation.selection.get': args => requireJob(args),\n    'generation.selection.commit': async (args, request = {}) => {\n      const job = await requireJob(args);\n      return exclusive(job.operationId, request, scoped => commit(job, args.expectedVersion, scoped));\n    },\n    'generation.selection.review': async (args, request = {}) => {\n      modelFor(request);\n      const job = await requireJob(args);\n      if (job.status === 'complete') return job;\n      if (!job.candidates?.length) throw new Error('There are no saved candidates to review');\n      return exclusive(job.operationId, request, async scoped => {\n        try {\n          const selection = await resolve(job.selection, scoped);\n          const sources = await evidence(selection, scoped);\n          const deck = { title: job.candidateTitle || 'Selected material', cards: clone(job.candidates) };\n          const structural = [...validateDeck(deck, sources).errors, ...learnerContextIssues(deck), ...explanationIssues(deck), ...answerLeakIssues(deck), ...formulaIssues(deck, { notation: resolveNotation('auto', sources) })];\n          const review = await reviewDeck(modelFor(scoped), { sources, deck, kind: job.request.kind, count: deck.cards.length, structuralErrors: structural, singleRound: true });\n          const issues = [...structural, ...reviewIssues(review, deck)];\n          const unattributed = issues.some(issue => !deck.cards.some(card => mentionsCard(issue, card, deck)));\n          const accepted = unattributed ? [] : deck.cards.filter(card =>\n            card.kind === job.request.kind && !issues.some(issue => mentionsCard(issue, card, deck)))\n            .slice(0, job.request.count).map(card => ({ ...card, id: randomUUID(), selections: [clone(selection)] }));\n          const saved = await save(job.operationId, { accepted, review, reviewPassed: accepted.length > 0,\n            status: accepted.length ? 'reviewed' : 'review-failed', error: accepted.length ? null : issues.join('; ') });\n          return accepted.length ? commit(saved, args.expectedVersion, scoped) : saved;\n        } catch (error) {\n          return save(job.operationId, { status: scoped.signal.aborted ? 'cancelled' : 'review-failed', error: errorText(error), reviewPassed: false, accepted: [] });\n        }\n      });\n    },\n  };\n  // The job layer wraps the very operations above: it only schedules them, tracks them and reports them (selection-jobs.js).\n  if (jobPorts) Object.assign(handlers, createSelectionJobs({ root, read, workOwner, resolve, evidence, normalize, clear, get, supplement, bank, complete,\n    commit: handlers['generation.selection.commit'], review: handlers['generation.selection.review'] }, jobPorts));\n  Object.defineProperty(handlers, 'dispose', { value: () => { for (const controller of ownedControllers) controller.abort(); } });\n  return handlers;\n}\n"
    },
    {
      "path": "lib/contexts/generation/jobs/publish-step.js",
      "content": "import { createHash } from 'node:crypto';\nimport { get } from '../../../util.js';\nimport { publicationTarget } from '../../../bank-import.js';\nimport { featureOf } from '../../../model-usage.js';\nimport { PUBLISH_STEP } from './publish-reconcile.js';\n\n/* The publication of a draft as a runtime job does it, for every job that publishes (the publication of a draft, the supplement's own at the end of its run):\n   the check (reviews through the gateway, and what the write will leave in the library), the plan kept on disk, then the write as a commit of the runtime.\n   `call(action, args)` is the context's own call to another context; `commit` is the runtime's `commitArtifact` (absent when the job is not kept on disk: the write is then\n   just done). */\n\n/** The reviews of a publication are the authoring context's work, and the usage summary has always told them so (not question writing). */\nexport const REVIEW_FEATURE = featureOf('authoring', 'draft.publish');\nconst digestOf = cardIds => createHash('sha256').update(JSON.stringify(cardIds)).digest('hex').slice(0, 12);\n\n/** The receipt of a write as the job keeps it: small and plain, so it can sit in the runtime's record. */\nexport const receiptOf = result => ({ id: result.id, deckId: result.deckId ?? null, accepted: result.accepted, rejected: result.rejected, added: result.added ?? 0,\n  total: result.total ?? null, autoReviewed: result.autoReviewed ?? 0, unchecked: result.unchecked ?? 0, remainingDraftId: result.rejectedDraft?.id ?? null });\n\n/** The write as the `result` the legacy publication call answers with (what a supplement run reads). */\nexport const resultOfReceipt = receipt => ({ ...receipt, rejectedDraft: receipt.remainingDraftId ? { id: receipt.remainingDraftId } : undefined });\n\n/** The check of a publication; one that an earlier Attempt already made (and kept) is not paid for again while the draft and the deck are what they were. */\nasync function planned({ call, read, plans, stepKey, base, ask, onProgress, draft, meta, quick }) {\n  const kept = await plans?.load(stepKey);\n  if (kept) {\n    const state = await read(), target = publicationTarget(state, get(state.drafts, draft.id, 'Draft'), base);\n    const same = kept.expect.draftId === draft.id && kept.expect.draftVersion === draft.draftVersion;\n    if (same && (kept.expect.before?.contentVersion ?? null) === (target ? target.contentVersion || 0 : null)) return kept;\n  }\n  const plan = { ...await call('draft.publish.plan', { ...base, ...(quick ? { quick: true } : { ask, onProgress }) }), deckTitle: draft.title, meta };\n  await plans?.save(stepKey, plan);\n  return plan;\n}\n\n/** Publish `draft` ({ id, draftVersion, title }) with `base` (the arguments of `draft.publish`); resolves with the receipt.\n * `meta` is kept with the plan for whoever finds the write done later. */\nexport async function publishDraft({ call, read, models, signal, commit, plans, stepKey = PUBLISH_STEP, base, draft, onProgress, meta, quick = false }) {\n  // The same batch asked twice (its reply could not be read) is told apart by how many times it was asked.\n  const asked = new Map();\n  const ask = (system, prompt, { cardIds }) => {\n    const key = digestOf(cardIds), retry = asked.get(key) ?? 0;\n    asked.set(key, retry + 1);\n    return models.call(system, prompt, { stage: 'Publication review', kind: 'review', unit: stepKey, card: key, retry, feature: REVIEW_FEATURE, signal });\n  };\n  const plan = await planned({ call, read, plans, stepKey, base, ask, onProgress, draft, meta, quick });\n  // The quick publication (a pasted case with answers) takes every question as it is: there is no review to have made and nothing to decide.\n  const write = async decided => receiptOf(quick ? await call('draft.publish.quick', { id: base.id, draftVersion: base.draftVersion })\n    : await call('draft.publish', { ...base, planned: true, publishDecision: decided.decision }));\n  return commit ? commit(stepKey, async () => plan, { publish: write }) : write(plan);\n}\n"
    },
    {
      "path": "lib/index.js",
      "content": "import { dshJobExecutor } from './jobs/executor.js';\n/* StudyHub for DeepSeek Harness (DSH): the plugin's server entry.\n   Contributed by ericwang1358 (https://github.com/EricWang1358). */\nimport { studyToolDescription, studyUsagePrompt } from './study-contracts.js';\nimport { registerStudySkills } from './study-skills.js';\nimport Schema from \"schemastery\";\nimport { boardAction } from \"./board.js\";\nimport { resolveAudioImportPaths } from './audio-files.js';\nimport { effectiveDirectory } from './working-directory.js';\nimport { scopeDiagramArgs } from './skeleton-diagrams.js';\nimport { acquireContexts } from './runtime/lifecycle.js';\nimport { fullContextIds } from './runtime/builtins.js';\nlet defineTool = definition => definition;\nlet llmSdk = {};\ntry { ({ defineTool } = await import('@deepseek-ai/dsh-tools')); }\ncatch (error) { if (error.code !== 'ERR_MODULE_NOT_FOUND') throw error; }\ntry { llmSdk = await import('@deepseek-ai/dsh-llm'); }\ncatch (error) { if (error.code !== 'ERR_MODULE_NOT_FOUND') throw error; }\nconst { BlockAssembler, createUserMessage, ReasoningEffortId } = llmSdk;\nimport {\n  binding,\n  saveBinding,\n  sessionModel,\n  modelStatus,\n  withModelStatus,\n  withSession,\n  serviceFor,\n  installTransport,\n  jsonSafe,\n  servicesForHost,\n} from \"./host.js\";\nimport {\n  listNotebooks,\n  publishNotebook,\n  unpublishNotebook,\n  searchNotebooks,\n} from \"./notebooks.js\";\nimport { parseSparInput, formatCapture } from \"./capture.js\";\nimport { runGenerationAgent } from \"./generation-agent.js\";\nimport { stageRequest } from \"./prompt-order.js\";\nimport { correctionEffort, runCorrectionAgent } from './live-correction-agent.js';\nimport { reasoningFor } from './model-effort.js';\nimport { parentOfChild } from './host-capabilities.js';\nimport { GENERATION_TIMEOUT_MS } from \"./generation-limits.js\";\nimport { hedgeFirstChunk, streamFailure } from \"./model-retry.js\";\nimport { createSessionNotifier } from \"./session-notice.js\";\nimport { effortRoute, modelEfforts, routeOnModel, withEffortPreference, withEffortState } from \"./reasoning-effort.js\";\nimport { acceptedEfforts, replacementEffort } from \"./effort-rejection.js\";\nimport { stageEffortRoute } from \"./stage-effort.js\";\nimport { usageFromTokenUsage } from \"./token-usage.js\";\n/** DSH's session query (`ctx.sessionQuery`) when the host has it: the jobs context reads a finished sub-agent's final reply through it (lib/session-reply.js). */\nconst hostSessionQuery = (ctx) => { try { return ctx?.get?.('sessionQuery') || undefined; } catch { return undefined; } };\n/** DSH's token estimator (`ctx.tokenMeter`) when the host has it; estimates fall back to its mirrored rule. */\nexport function hostTokenMeter(ctx) {\n  try { return ctx?.get?.(\"tokenMeter\") || undefined; } catch { return undefined; }\n}\nimport { reportUsage } from \"./usage-scope.js\";\nimport { retrievalPort } from \"./retrieval-host.js\";\nimport { assistantArgsRefusal, assistantRefusal } from \"./assistant-boundary.js\";\nimport { readAudioSettings } from \"./audio-settings.js\";\nimport { RuntimeConfig } from \"./runtime-config.js\";\n\nconst LIGHT_TIMEOUT_MS = 90000;\nconst LIGHT_HEDGE_MS = 15000;\n\nexport const name = \"daily-flashcard\";\n// Tool and command closures also resolve the live session's model route.\n// Cordis requires this in the parent scope, not only in the panel transport.\nexport const inject = [];\nexport const Config = Schema.object({\n  libraryRoot: Schema.string().default(\"\"),\n  provider: Schema.string().default(\"\"),\n  model: Schema.string().default(\"\"),\n  modular: Schema.boolean().default(false),\n  contexts: Schema.array(Schema.string()).default(fullContextIds),\n  runtime: RuntimeConfig,\n});\n/* Passive panel context waits for the next step; terminal generation receipts\n   start a reporting turn in the session that initiated the task. */\nexport const sessionNotifier = (agent) => createSessionNotifier(agent, createUserMessage, name);\n// Cheapest thinking level per exact route: off/none/minimal when offered, else low.\nconst lightEfforts = new WeakMap();\n// Levels a provider refused (2.6.1): provider/model/level -> the level it takes instead ('' = send none). See lib/effort-rejection.js.\nconst refusedEfforts = new Map();\nexport function pickLightEffort(efforts = []) {\n  const find = (re) => efforts.find((e) => re.test(String(e.id)) || re.test(String(e.name)));\n  const off = find(/^(off|none|disabled?|no[-_ ]?think(ing)?|minimal|non[-_ ]?thinking)$/i);\n  if (off) return { id: String(off.id), off: true };\n  const low = find(/low/i);\n  if (low) return { id: String(low.id), off: false };\n  // Some routes only offer e.g. high/max; efforts are listed in the adapter's\n  // order (lowest first in DSH catalogs), so take the first rather than the default.\n  return efforts.length ? { id: String(efforts[0].id), off: false } : null;\n}\nasync function lightEffort(ctx, provider, model, signal) {\n  let cache = lightEfforts.get(ctx);\n  if (!cache) lightEfforts.set(ctx, cache = new Map());\n  const key = provider + \"\\0\" + model;\n  if (!cache.has(key))\n    cache.set(key, ctx.llm.resolveModelInfo?.(provider, model, signal)\n      .then((info) => pickLightEffort(info?.reasoning?.efforts))\n      .catch(() => {\n        cache.delete(key);\n        return null;\n      }) ?? Promise.resolve(null));\n  return cache.get(key);\n}\nconst refusedKey = (route, id) => `${route.provider}\\0${route.model}\\0${id}`;\n/** True when `error` is a provider's \"invalid reasoning_effort\" answer for a level we sent and a replacement is now remembered (retry is worth it). */\nasync function rememberRefusedEffort(ctx, error, signal) {\n  const sent = error?.effortSent, accepted = sent && acceptedEfforts(error?.message);\n  if (!accepted || signal?.aborted || refusedEfforts.has(refusedKey(sent, sent.id))) return false;\n  let offered = [];\n  try { offered = (await modelEfforts(ctx, sent.provider, sent.model, signal)).map((item) => item.id); } catch { /* none: send no level */ }\n  refusedEfforts.set(refusedKey(sent, sent.id), replacementEffort(sent.id, accepted, offered) ?? '');\n  return true;\n}\n/**\n * @param route - returns the provider/model to call, resolved per request.\n * @param options.light - 陪学 calls: lowest reasoning effort and, when thinking\n *   is fully off, a capped output so a chatty reply cannot burn tokens.\n * @param options.lightTimeoutMs / options.hedgeMs - per-attempt budget and the\n *   no-first-chunk delay before a light call races a second request.\n */\nexport function modelCompletion(ctx, route, sessionId, { light = false, lightTimeoutMs = LIGHT_TIMEOUT_MS, hedgeMs = LIGHT_HEDGE_MS } = {}) {\n  if (!BlockAssembler || !ctx.llm) throw new Error('Model capability unavailable: DSH model SDK is absent');\n  /* One streamed call. ctx.llm.stream never throws for provider problems: a\n     rate limit, transport error or our own timeout abort all arrive as an\n     `error`/`aborted` finish chunk. Read it, so a 90s timeout is reported as a\n     timeout (and not retried as if the model had merely answered empty). */\n  const complete = async (...args) => {\n    try { return await completeOnce(...args); }\n    catch (error) {\n      // The provider refused the level DSH sent: ask again once with the nearest level it names as accepted.\n      if (!(await rememberRefusedEffort(ctx, error, args[3]))) throw error;\n      return completeOnce(...args);\n    }\n  };\n  const completeOnce = async (system, prompt, timeoutMs = 180000, externalSignal, maxTokens, task = \"light\", onChunk, correctionReasoning, selectedRoute, sink) => {\n    const started = performance.now();\n    const timeout = AbortSignal.timeout(timeoutMs);\n    const signal = AbortSignal.any([timeout, ...(externalSignal ? [externalSignal] : [])]),\n      chosen = selectedRoute || route();\n    if (!chosen) throw new Error(\"No model is available for generation\");\n    // The learner's generation level (Settings) applies to question work only:\n    // 陪学 forces the lowest level and corrections / audio carry their own.\n    const selected = light || correctionReasoning ? chosen : await effortRoute(ctx, chosen, signal);\n    const effort = light && !correctionReasoning ? await lightEffort(ctx, selected.provider, selected.model, signal) : null;\n    let reasoningEffort = effort?.id ?? selected.reasoningEffort;\n    if (correctionReasoning) {\n      // A correction never inherits the parent chat's high reasoning setting.\n      reasoningEffort = await correctionEffort(ctx, selected, correctionReasoning, signal);\n    }\n    const refusal = reasoningEffort === undefined ? undefined : refusedEfforts.get(refusedKey(selected, reasoningEffort));\n    if (refusal !== undefined) reasoningEffort = refusal || undefined;\n    const call = await ctx.llm.resolveCallConfig(\n      {\n        provider: selected.provider,\n        model: selected.model,\n        ...(reasoningEffort === undefined\n          ? {}\n          : { reasoningEffort: ReasoningEffortId(reasoningEffort) }),\n        ...(((effort?.off && refusal === undefined) || correctionReasoning || task === 'assist') && maxTokens ? { maxTokens } : {}),\n      },\n      signal,\n    );\n    const assembler = new BlockAssembler();\n    const configured = performance.now();\n    let firstChunk = null,\n      firstText = null,\n      outcome = \"failed\";\n    try {\n      for await (const chunk of ctx.llm.stream({\n        ...call,\n        system,\n        messages: [\n          createUserMessage({ content: [{ type: \"text\", text: prompt }] }),\n        ],\n        sessionId,\n        signal,\n      })) {\n        if (firstChunk === null) {\n          firstChunk = performance.now();\n          onChunk?.();\n        }\n        if (firstText === null && chunk.type === \"text-delta\") firstText = performance.now();\n        assembler.push(chunk);\n        // What the model writes on the way, for the console's 实时输出 (lib/job-output.js): the answer's text, and only the size of its reasoning.\n        if (sink) { if (chunk.type === \"text-delta\") sink.text?.(chunk.text); else if (chunk.type === \"reasoning-delta\") sink.reasoning?.(chunk.text.length); }\n      }\n      const finish = assembler.finish;\n      if (finish?.kind === \"error\" || finish?.kind === \"aborted\" || signal.aborted) {\n        if (externalSignal?.aborted && !timeout.aborted) outcome = \"cancelled\";\n        throw Object.assign(streamFailure(finish, { timedOut: timeout.aborted, timeoutMs }), { modelFailure: true });\n      }\n      const text = assembler\n        .blocks()\n        .filter((b) => b.type === \"text\")\n        .map((b) => b.text)\n        .join(\"\");\n      if (!text.trim()) throw Object.assign(new Error(\"Model returned no text\"), { modelFailure: true });\n      outcome = \"ok\";\n      return text;\n    } catch (error) {\n      if (error && typeof error === \"object\" && !error.modelFailure && (timeout.aborted || externalSignal?.aborted)) {\n        if (externalSignal?.aborted && !timeout.aborted) outcome = \"cancelled\";\n        throw Object.assign(streamFailure(null, { timedOut: timeout.aborted, timeoutMs }), { modelFailure: true, cause: error });\n      }\n      if (error && typeof error === \"object\" && reasoningEffort !== undefined) Object.assign(error, { effortSent: { provider: selected.provider, model: selected.model, id: String(reasoningEffort) } });\n      throw error;\n    } finally {\n      const ended = performance.now();\n      // What the provider billed for this attempt, answered or not (WP27); a sink can never break the call.\n      reportUsage(usageFromTokenUsage(assembler.usage), { calls: 1, task });\n      if (light && outcome !== \"cancelled\" && ended - started >= 2000)\n        console.warn(`[study-model] ${task} ${outcome}: config ${Math.round(configured - started)}ms, first chunk ${firstChunk === null ? \"none\" : Math.round(firstChunk - configured) + \"ms\"}, first text ${firstText === null ? \"none\" : Math.round(firstText - configured) + \"ms\"}, generation ${firstText === null ? 0 : Math.round(ended - firstText)}ms, total ${Math.round(ended - started)}ms`);\n    }\n  };\n  const correct = (system, prompt, options) => complete(system, prompt, lightTimeoutMs, options.signal, options.maxTokens, options.task, undefined, options.reasoningEffort || 'low');\n  const attachChild = fn => Object.assign(fn, { spawnCorrection: (system, prompt, options = {}) => {\n    const selected = route();\n    return runCorrectionAgent(ctx, selected, sessionId, system, prompt, options,\n      () => complete(system, prompt, lightTimeoutMs, options.signal, options.maxOutputTokens || 4096, 'live.correct.background', undefined, options.reasoningEffort || 'low', selected));\n  } });\n  if (light)\n    // A request that has not produced a single chunk after 15s is usually\n    // stuck in the provider's queue; race a fresh one instead of waiting 90s.\n    // A caller that names a reasoning level (为你定制's batches, lib/coach-daily.js) gets that level instead of the lowest one the light path uses by default.\n    return attachChild((system, prompt, options = {}) => options.task?.startsWith('live.correct') || options.reasoningEffort\n      ? correct(system, prompt, options)\n      // A stop from the caller (a Job's signal) ends every attempt of the race, not only the one that has not started.\n      : hedgeFirstChunk((signal, onChunk) => complete(system, prompt, lightTimeoutMs, options.signal ? AbortSignal.any([signal, options.signal]) : signal, options.maxTokens, options.task, onChunk), { hedgeMs }));\n  const audio = async (system, prompt, execution) => {\n    const selected = route();\n    // The preference is a relative strength; the nearest level this model offers is used, and the task says which and why.\n    const choice = await reasoningFor(ctx, selected, execution.reasoningEffort, execution.signal);\n    execution.onEvent?.({ reasoningEffort: choice.id ?? 'default', reasoningName: choice.name, reasoningApplied: choice.applied,\n      ...(choice.reason ? { reasoningReason: choice.reason } : {}) });\n    // The task keeps which session the sub-agent runs under, so the panel can ask DSH to list it before opening it.\n    const watched = execution.onEvent ? { ...execution, onEvent: (event) => execution.onEvent(event?.childId ? { ...event, parentId: parentOfChild(event.childId) } : event) } : execution;\n    return runGenerationAgent(ctx, { ...selected, reasoningEffort: choice.id }, sessionId, system, prompt, watched,\n      () => complete(system, prompt, GENERATION_TIMEOUT_MS, execution.signal, undefined, 'audio.text', undefined, execution.reasoningEffort, selected, { text: execution.onOutput, reasoning: execution.onReasoning }));\n  };\n  /** A question-generation phase: the learner's level, recorded on the step that used it. */\n  const generation = async (stageSystem, stagePrompt, execution) => {\n    // What the stages of a part share (their sources) leads the request, the stage's own system text behind it (lib/prompt-order.js stageRequest): the provider caches that start.\n    const { system, prompt } = stageRequest(stageSystem, stagePrompt);\n    // The model the learner chose for this run (lib/job-model.js), else the host's; the session's level, then the stage's own (planning/review/writing/repair) when the learner set one for it (#218).\n    const base = await routeOnModel(ctx, route(), execution.model, execution.signal);\n    const staged = await stageEffortRoute(ctx, await effortRoute(ctx, base, execution.signal), execution.stage, execution.stageEffort, execution.signal);\n    const selected = staged.route;\n    if (selected?.reasoningEffort !== undefined || staged.choice) execution.onEvent?.({ reasoningEffort: String(selected?.reasoningEffort ?? 'default'),\n      ...(staged.choice ? { reasoning: staged.choice.preference, reasoningName: staged.choice.name, reasoningApplied: staged.choice.applied,\n        ...(staged.choice.reason ? { reasoningReason: staged.choice.reason } : {}) } : {}) });\n    return runGenerationAgent(ctx, selected, sessionId, system, prompt, execution,\n      () => complete(system, prompt, GENERATION_TIMEOUT_MS, execution.signal, undefined, undefined, undefined, undefined, selected, { text: execution.onOutput, reasoning: execution.onReasoning }));\n  };\n  return attachChild((system, prompt, execution) => execution?.task === 'assist'\n    ? complete(system, prompt, 8 * 60 * 1000, execution.signal, execution.maxTokens, 'assist', undefined, undefined, execution.route, { text: execution.onOutput, reasoning: execution.onReasoning })\n    : execution?.resultOwner === 'plugin' && execution.reasoningEffort ? audio(system, prompt, execution)\n    : execution?.task?.startsWith('live.correct') ? correct(system, prompt, execution)\n    // Only a question-generation phase carries a job id (its worker is labelled with it). A request with just a signal, such as the\n    // answer about a selected passage, is one plain call: sending it to the generation worker failed on `execution.jobId.slice`.\n    : execution?.jobId ? generation(system, prompt, execution)\n    : complete(system, prompt, undefined, execution?.signal, execution?.maxTokens));\n}\nfunction installWorkbench(ctx, config = {}) {\n  const hostCtx = ctx.root || ctx;\n  const owned = servicesForHost(ctx, config.runtime?.resources, config.runtime?.pilot), { bridge } = owned;\n  if (hostCtx[workbenchScope]) hostCtx[workbenchScope].services = owned;\n  const makeComplete = (route, id, options) => modelCompletion(hostCtx, route, id, options);\n  installTransport(ctx, config, makeComplete);\n  ctx.inject([\"commands\"], (c) => {\n    c.commands.register({\n      name: \"study-spar\",\n      description: \"把不会的问题归类进题库：自动判断范围与原题，默认存为闪卡\",\n      input: { hint: \"[前置] <不会的问题>（加“写成 MQ”存为单选题；以“前置”开头则挂到正在做的题上）\" },\n      handler: async ({ agent, rawInput }) => {\n        const { question, kind, prerequisite } = parseSparInput(rawInput);\n        if (!question)\n          return {\n            kind: \"error\",\n            text: \"用法：/study-spar <不会的问题>。默认存为闪卡；加“写成 MQ”存为单选题，“写成多选题”存为多选题。\",\n          };\n        const cwd = agent?.session?.header?.cwd;\n        if (!cwd) return { kind: \"error\", text: \"当前会话没有工作区，无法打开学习库。\" };\n        try {\n          const service = await serviceFor(\n            hostCtx,\n            config,\n            cwd,\n            agent.session,\n            makeComplete,\n            agent.id,\n            sessionNotifier(agent),\n            ctx,\n          );\n          return {\n            kind: \"success\",\n            text: formatCapture(\n              await service.call(\"capture\", {\n                question,\n                kind,\n                ...(prerequisite ? { requiredBy: \"current\" } : {}),\n              }),\n            ),\n          };\n        } catch (e) {\n          return { kind: \"error\", text: `没能加入题库：${e.message}` };\n        }\n      },\n    });\n  });\n  ctx.inject(['tools', 'sessions'], toolCtx => toolCtx.tools.register(\n    defineTool({\n      name: \"study_workspace\",\n      description: studyToolDescription,\n      parameters: {\n        action: { type: \"string\", required: true },\n        payload_json: {\n          type: \"string\",\n          description: \"JSON object of action arguments; omit for read actions\",\n        },\n      },\n      output: {\n        schema: { type: \"object\", additionalProperties: true },\n        render: (_args, value) => [\n          { type: \"text\", text: JSON.stringify(value) },\n        ],\n      },\n      async execute(a, exec) {\n        const value = jsonSafe(await runStudyTool(a, exec));\n        // The output schema is an object; DSH rejects null, arrays and scalars\n        // with `\"value\" must be an object`, failing the whole code run.\n        return value && typeof value === \"object\" && !Array.isArray(value)\n          ? value\n          : { result: value };\n      },\n    }),\n  ));\n  /** Runs one study_workspace call; execute normalizes the result to lossless JSON. */\n  async function runStudyTool(a, exec) {\n    const agent = exec.agent,\n      cwd = agent?.session?.header?.cwd;\n    if (!cwd) throw new Error(\"A session workspace is required\");\n    // The learner's own usage record and Settings-only actions (programs, installs, models, tokens, consent) are refused by name (lib/assistant-boundary.js).\n    const refusal = assistantRefusal(a.action);\n    if (refusal) throw new Error(refusal);\n    let args = {};\n    if (a.payload_json) {\n      try {\n        args = JSON.parse(a.payload_json);\n      } catch (e) {\n        throw new Error(\n          `payload_json is not valid JSON (${e.message}); send the action arguments as a JSON object string`,\n        );\n      }\n    }\n    // live.start with a provider is checked against the learner's saved engine choice (it never leaves this computer for the check).\n    const liveProvider = a.action === \"live.start\" && args?.provider !== undefined ? (await readAudioSettings()).liveProvider : undefined;\n    const argsRefusal = assistantArgsRefusal(a.action, args, { liveProvider });\n    if (argsRefusal) throw new Error(argsRefusal);\n    if (a.action.startsWith(\"board.\")) return boardAction(a.action, args, cwd);\n    const followed = () => sessionModel(hostCtx, agent.session);\n    if (a.action.startsWith(\"notebook.\")) {\n      const root = (await binding(cwd, config)).root;\n      if (a.action === \"notebook.publish\") await publishNotebook(cwd, root);\n      else if (a.action === \"notebook.unpublish\") await unpublishNotebook(root);\n      else if (a.action === \"notebook.search\")\n        return searchNotebooks(args.query);\n      else if (a.action !== \"notebook.list\")\n        throw new Error(`Unknown action: ${a.action}`);\n      return listNotebooks(root);\n    }\n    // `model` stays the custom model id; the C3 readiness rides beside it.\n    const bound = async () => {\n      const value = await binding(cwd, config, followed());\n      value.modelStatus = await modelStatus(hostCtx, value.route);\n      await withEffortState(hostCtx, value);\n      return value;\n    };\n    if (a.action === \"binding.get\")\n      return bound();\n    if (a.action === \"binding.set\") {\n      await saveBinding(cwd, args);\n      return bound();\n    }\n    const service = await serviceFor(\n      hostCtx,\n      config,\n      cwd,\n      agent.session,\n      makeComplete,\n      agent.id,\n      sessionNotifier(agent),\n      ctx,\n    );\n    bridge.registerPanelNotifier(agent.id, sessionNotifier(agent));\n    if (a.action === \"panel.current\") {\n      return { current: bridge.hasPanelVisibility(agent.id) ? bridge.panelObservation(agent.id) : null };\n    }\n    if (a.action === \"panel.open\") {\n      const current = await service.call(\"snapshot\", { compact: true });\n      const returnTo = current.lastRun?.id || null;\n      // Hand a round to the right panel and say only what the host confirmed (#537): visible, deferred by the learner's own activity, or queued.\n      const deliver = async (run, focus, extra = {}) => {\n        const intentResult = bridge.queuePanelIntent(agent.id, { type: \"run\", runId: run.id, expectedFocus: focus });\n        const ackTimeout = typeof args.ackTimeoutMs === 'number' ? args.ackTimeoutMs : 2200;\n        const ack = await bridge.waitForIntentAck(agent.id, intentResult.intentId, ackTimeout);\n        const isVisible = ack && ack.status === 'displayed';\n        const isDeferred = ack && ack.status === 'deferred_by_user_activity';\n        const status = isVisible ? 'visible_in_sidebar' : isDeferred ? 'deferred_by_user_activity' : 'queued_for_sidebar';\n        return { status, confirmed: !!isVisible, intentId: intentResult.intentId, runId: run.id, ...extra };\n      };\n      const focusOf = (run) => (run.card ? { cardId: run.card.id, deckId: run.deckId } : null);\n      // A round that already exists (#551): the one the learner asked for, as it is (its order, position, answers and drafts), never a new one.\n      if (args.runId !== undefined) {\n        if (typeof args.runId !== \"string\" || !args.runId) throw new Error(\"runId must name a round (review.start / review.get)\");\n        const run = await service.call(\"review.get\", { runId: args.runId });\n        if (run.closed) throw new Error(\"This round has ended; start a new one with review.start or panel.open {scope}\");\n        return deliver(run, focusOf(run), { index: run.index, total: run.total, title: run.title });\n      }\n      // Several named questions as one round, in the order given; an open round over exactly these is resumed, not started again.\n      if (args.scope !== undefined) {\n        if (!Array.isArray(args.scope) || !args.scope.length || args.scope.length > 200 || args.scope.some((ref) => !ref?.cardId))\n          throw new Error(\"scope is 1–200 questions [{deckId?, cardId}]\");\n        const scope = [];\n        for (const ref of args.scope) { const { deck, card } = await service.call(\"card.locate\", ref); scope.push({ deckId: deck.id, cardId: card.id }); }\n        const run = await service.call(\"review.start\", { mode: \"path\", scope, ...(returnTo ? { returnTo } : {}) });\n        return deliver(run, focusOf(run), { index: run.index, total: run.total, returnTo });\n      }\n      let candidates;\n      if (args.cardId) {\n        const { deck, card } = await service.call(\"card.locate\", args);\n        candidates = [{ deckId: deck.id, deckTitle: deck.title, cardId: card.id,\n          kind: card.kind, topic: card.topic, prompt: String(card.prompt).slice(0, 160) }];\n      } else {\n        if (typeof args.query !== \"string\" || !args.query.trim())\n          throw new Error(\"请给出题目关键词、cardId、scope:[{deckId,cardId}] 或已有一轮的 runId\");\n        const found = await service.call(\"card.search\", { query: args.